import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.DoCD98hS.js";const h=JSON.parse('{"title":"qiankun 2 · 页签核心与主微应用模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/qiankun.md","filePath":"modules/catalog/qiankun.md","lastUpdated":1795231846000}'),r={name:"modules/catalog/qiankun.md"};function c(i,t,n,l,u,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="qiankun-2-·-页签核心与主微应用模板" tabindex="-1">qiankun 2 · 页签核心与主微应用模板 <a class="header-anchor" href="#qiankun-2-·-页签核心与主微应用模板" aria-label="Permalink to &quot;qiankun 2 · 页签核心与主微应用模板&quot;">​</a></h1><p>Vue 2.7 和 Vue 3 都可以作为主应用，挂载 Vue、React 等不同框架的子应用。主应用用远程 Tab 和内容容器打开页面，子应用通过 qiankun 生命周期挂载。</p><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-qiankun2-tabs-core</code></td><td>框架无关的页签身份、路由状态与微应用运行时</td></tr><tr><td><code>@melt-js/libs-qiankun2-tabs-vue3</code></td><td>Vue 3 页签管理与宿主 / 子应用适配</td></tr><tr><td><code>@melt-js/libs-qiankun2-tabs-vue2</code></td><td>Vue 2.7 页签管理、页签 UI、缓存与微应用保活适配（<code>Vue.use</code> 注册，不支持 2.6 及以下）</td></tr><tr><td><code>@melt-js/libs-qiankun2-tabs-react</code></td><td>React 子应用、路由与页面缓存适配</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-cli5-main</code></td><td>主应用 · Vue 3 CLI5，挂载 app1 至 app4</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-cli4-main</code></td><td>主应用 · Vue 2.7 CLI4，挂载同一批子应用</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-cli5-app1</code></td><td>子应用 App1 · Vue 3 CLI5，演示用户子路由、保活、远程榜单和分类选择器</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-vite-app2</code></td><td>子应用 App2 · Vue 3 + Vite，演示生命周期和临时表单</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-cli4-app3</code></td><td>子应用 App3 · Vue 2.7 CLI4，演示远程表单、列表和从夯到拉</td></tr><tr><td><code>@melt-js/tpl-qiankun2-react-vite-app4</code></td><td>子应用 App4 · React + Vite，演示 React 页签和保活</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><p>两个主应用共用下表的四个子应用。选一个主应用体验完整的页签交互，或单独打开子应用查看它自己的页面。</p><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td>主应用 · Vue 3 CLI 5</td><td><a href="https://melt-js.github.io/tpl-qiankun2-vue3-cli5-main/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td>主应用 · Vue 2.7 CLI 4</td><td><a href="https://melt-js.github.io/tpl-qiankun2-vue2-cli4-main/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td>子应用 App1 · Vue 3 CLI 5</td><td><a href="https://melt-js.github.io/tpl-qiankun2-vue3-cli5-app1/dist/index.html" target="_blank" rel="noreferrer">独立打开 App1</a></td></tr><tr><td>子应用 App2 · Vue 3 + Vite</td><td><a href="https://melt-js.github.io/tpl-qiankun2-vue3-vite-app2/dist/index.html" target="_blank" rel="noreferrer">独立打开 App2</a></td></tr><tr><td>子应用 App3 · Vue 2.7 CLI 4</td><td><a href="https://melt-js.github.io/tpl-qiankun2-vue2-cli4-app3/dist/index.html" target="_blank" rel="noreferrer">独立打开 App3</a></td></tr><tr><td>子应用 App4 · React + Vite</td><td><a href="https://melt-js.github.io/tpl-qiankun2-react-vite-app4/dist/index.html" target="_blank" rel="noreferrer">独立打开 App4</a></td></tr></tbody></table><p>子应用单独打开时是独立页面，只有通过主应用进入才能验证页签、保活与路由同步。</p><h2 id="在主应用体验" tabindex="-1">在主应用体验 <a class="header-anchor" href="#在主应用体验" aria-label="Permalink to &quot;在主应用体验&quot;">​</a></h2><p>用左侧菜单连续打开两个子页面，在保活页面填写内容后切走再返回。再关闭并重开页签，观察页面是否重建。需要检查打开、切换或关闭时的行为，点主应用顶部的「API 演示」或「事件日志」。</p><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>core：<code>MicroAppRuntime</code> / <code>RouteDispatcher</code> / <code>MicroPageCache</code></td><td>运行时、路由调度与页面缓存</td></tr><tr><td>Vue 3：<code>installMicroTabsBridge</code> / <code>createMicroAppCache</code></td><td>主应用桥接与微应用缓存</td></tr><tr><td>Vue 3：<code>useTabQuery</code> / <code>createTabsUrlSync</code></td><td>页签查询状态与 URL 同步</td></tr><tr><td>Vue 2：<code>createTabsManager</code> / <code>tabsManager</code> 插件</td><td>页签管理器创建与 <code>Vue.use</code> 注册（内部完成 registerModules 与 setupPlugins）</td></tr><tr><td>Vue 2：<code>createMicroAppCache</code> / <code>useMicroAppCache</code>（<code>/child</code> 子路径）</td><td>子应用 keep-alive 缓存模型，输出 <code>state.keepAliveList</code> 与 <code>cache.key()</code></td></tr><tr><td>Vue 2：<code>createMicroTabController</code> / <code>installMicroTabsBridge</code> / <code>createTabsUrlSync</code></td><td>子应用页签控制、宿主消息桥接与 URL 同步</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td>Vue 3：<code>MicroAppView</code> 与页签 UI</td><td>微应用容器与标签页</td></tr><tr><td>Vue 2：<code>DynamicTabsComponent</code> / <code>DynamicContainerComponent</code></td><td>动态页签与容器组件</td></tr></tbody></table><h2 id="接入页签" tabindex="-1">接入页签 <a class="header-anchor" href="#接入页签" aria-label="Permalink to &quot;接入页签&quot;">​</a></h2><ol><li>在 <code>main.js</code> 中沿用项目的 HEL 运行环境，加载与你的主应用框架对应的页签适配层，确认 <code>createTabsAdapter</code> 就绪后再进入业务入口。参见<a href="./../../guide/micro-frontend-tabs.html#在主应用加载页签">主应用预加载示例</a>。</li><li>Vue 3 在业务入口安装通过 <code>createQiankunTabsHost</code> 创建的插件；Vue 2.7 使用 <code>Vue.use</code> 安装页签插件。布局从对应适配包的 <code>/remote</code> 导入 <code>DynamicTabsComponent</code> 和 <code>DynamicContainerComponent</code>。保留应用自己的菜单与业务页面。</li><li>主应用为每个子应用配置独立名称、HTML <code>entry</code>、路由前缀 <code>activeRule</code> 与 <code>defaultPath</code>，由 <code>loadMicroApp</code> 挂载。子应用同步导出 <code>bootstrap</code>、<code>mount</code>、<code>unmount</code> 和 <code>update</code>；如需远程依赖，在生命周期内等待加载，再进入实际业务模块。</li><li>用子应用路由桥协调页签导航，应用各自携带匹配的框架运行时。通过主应用验证同一子应用多个页签可以独立切换，表单状态和滚动符合缓存设置。</li></ol><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p>Vue 2 模板来自 qiankun-tabsCache，Vue 3 模板来自 qiankun-vue3-tabsPage。两个主应用可以分别挂载同一套子应用，子应用选择自己的框架运行时，主应用统一管理导航和页签。</p>',18)])])}const b=e(r,[["render",c]]);export{h as __pageData,b as default};
